class Solution {
    bool canForm(const string& word, const unordered_set<string>& wordSet) {
        if (wordSet.empty()) return false;
        int n = word.size();
        vector<bool> dp(n + 1, false);
        dp[0] = true;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (dp[j] && wordSet.count(word.substr(j, i - j))) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n];
    }
public:
    vector<string> findAllConcatenatedWordsInADict(vector<string>& words) {
        sort(words.begin(), words.end(), [](const string& a, const string& b) {
            return a.size() < b.size();
        });
        unordered_set<string> wordSet;
        vector<string> res;
        for (const string& w : words) {
            if (canForm(w, wordSet)) {
                res.push_back(w);
            }
            wordSet.insert(w);
        }
        return res;
    }
};

class Solution {
    private boolean canForm(String word, Set<String> wordSet) {
        if (wordSet.isEmpty()) return false;
        int n = word.length();
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j < i; ++j) {
                if (dp[j] && wordSet.contains(word.substring(j, i))) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n];
    }
    public List<String> findAllConcatenatedWordsInADict(String[] words) {
        Arrays.sort(words, Comparator.comparingInt(String::length));
        Set<String> wordSet = new HashSet<>();
        List<String> res = new ArrayList<>();
        for (String w : words) {
            if (canForm(w, wordSet)) {
                res.add(w);
            }
            wordSet.add(w);
        }
        return res;
    }
}

var findAllConcatenatedWordsInADict = function(words) {
    words.sort((a, b) => a.length - b.length);
    const wordSet = new Set();
    const res = [];

    function canForm(word) {
        if (wordSet.size === 0) return false;
        const n = word.length;
        const dp = new Array(n + 1).fill(false);
        dp[0] = true;
        for (let i = 1; i <= n; ++i) {
            for (let j = 0; j < i; ++j) {
                if (dp[j] && wordSet.has(word.slice(j, i))) {
                    dp[i] = true;
                    break;
                }
            }
        }
        return dp[n];
    }

    for (const w of words) {
        if (canForm(w)) res.push(w);
        wordSet.add(w);
    }
    return res;
};
